// === Tab: mySketch ===
// 17
// For the #WCCChallenge << 17 Squares >> (join the discord! https://discord.gg/S8c7qcjw2b)
// Short and sweet one this time
let numSquares = 17;
let baseSize = 80;
let squareSize = 400;
let amp = 200;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  angleMode(RADIANS);
  colorMode(HSB);
  noFill();
  strokeWeight(5);
  strokeJoin(MITER);
	rectMode(CENTER);
}

function draw() {
  // === Variant 4: Dynamic Feedback Trail ===
  // Lower background clear to force deep visual echoing

  background(10, 10, 15, 6);
  orbitControl();

  let t = millis() * 0.0006;

  for (let i = 0; i < numSquares; i++) {
    let angle = TAU * i / numSquares;
    let y = amp * sin(t + angle);
    let s = abs(baseSize + squareSize * cos(t + angle));

    let h = map(angle, 0, TWO_PI, 0, 360);
    stroke(h, 100, 100);

    push();
    translate(0, y, 0);
    rotateX(HALF_PI);
    rect(0, 0, s, s);
    pop();
  }
}
